import { gsap } from 'gsap';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, vec2, uniform, texture, normalMap, emissiveIntensity } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // ============================================================================
  // DESIGN TOKENS & CONSTANTS
  // ============================================================================
  const colors = {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  const cardW = 1.6;
  const cardH = 1.0;
  const cardPitch = 1.85;
  const numCards = 5;
  const stripRotY = -Math.PI / 10; // -18 degrees
  const focusScale = 1.0;
  const blurScale = 0.92;
  const focusOpacity = 1.0;
  const maxBlurOpacity = 0.55;
  const focusCardX = 0;

  const bevelSize = 0.025;
  const accentBarH = 0.035;
  const accentBarW = cardW;
  const accentEmissive = 1.3;
  const parallelIntensity = 0.5;

  const cardTexts = [
    'NA-01 MERIDIAN',
    'NA-02 NOCTURNE',
    'NA-03 SIGNAL',
    'NA-04 VANTAGE',
    'NA-05 ARCHIVE',
  ];

  // ============================================================================
  // STAGE BACKDROP (vertical gradient plane)
  // ============================================================================
  const stageGeom = new THREE.PlaneGeometry(7, 6);
  const stageMat = new MeshBasicNodeMaterial({
    color: new THREE.Color(colors.background),
  });
  const stage = new THREE.Mesh(stageGeom, stageMat);
  stage.position.z = -2.5;
  stage.renderOrder = -1;
  group.add(stage);

  // ============================================================================
  // LIGHTING
  // ============================================================================
  const ambLight = new THREE.AmbientLight(0xffffff, 0.6);
  group.add(ambLight);

  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2.5, 3.5, 3);
  group.add(keyLight);

  const rimLight = new THREE.DirectionalLight(0xff4444, 0.8);
  rimLight.position.set(-3, 2, 2);
  group.add(rimLight);

  // ============================================================================
  // TEXT ELEMENTS
  // ============================================================================
  const headlineText = ctx.fontAtlas.createText('The collection', {
    fontSize: 68,
    color: colors.paper,
    align: 'left',
  });
  headlineText.position.set(-2.6, 1.5, 0);
  group.add(headlineText);

  const bodyText = ctx.fontAtlas.createText('Five calibres. One discipline.', {
    fontSize: 26,
    color: colors.paper,
    align: 'left',
  });
  bodyText.position.set(-2.6, -1.5, 0);
  group.add(bodyText);

  // ============================================================================
  // CARD CONTAINER (will rotate together)
  // ============================================================================
  const cardContainer = new THREE.Group();
  cardContainer.rotation.y = stripRotY;
  group.add(cardContainer);

  // ============================================================================
  // CARD FACTORY
  // ============================================================================
  const cards = [];
  let mainTexture = null;

  const loadImageVariant = (index) => {
    const baseUrl = config.imageUrl || '/prism-mock/home/nodes/parallax-stack.png';
    const variantUrl = baseUrl.replace(/\.png$/, `_card${index}.png`);
    return ctx.textureLoader.loadTexture(variantUrl).catch(() => {
      return ctx.textureLoader.loadTexture(baseUrl);
    });
  };

  const createCard = async (index) => {
    const cardGroup = new THREE.Group();
    const xPos = (index - 2) * cardPitch;
    cardGroup.position.x = xPos;
    cardGroup.userData.index = index;
    cardGroup.userData.targetX = xPos;
    cardGroup.userData.targetRotY = 0;
    cardGroup.userData.targetOpacity = index === 2 ? focusOpacity : maxBlurOpacity;
    cardGroup.userData.targetScale = index === 2 ? focusScale : blurScale;
    cardGroup.userData.isFocused = index === 2;

    // Load texture for this card
    const texture = await loadImageVariant(index);
    if (index === 0) {
      mainTexture = texture;
    }

    // Card main geometry
    const cardGeom = new THREE.PlaneGeometry(cardW, cardH);
    const cardMat = new MeshStandardNodeMaterial({
      map: texture,
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      side: THREE.FrontSide,
    });

    const cardMesh = new THREE.Mesh(cardGeom, cardMat);
    cardMesh.position.z = 0;
    cardGroup.add(cardMesh);

    // Bevel frame (ink-colored border)
    const frameMats = [];
    for (let i = 0; i < 4; i++) {
      const frameMat = new MeshStandardNodeMaterial({
        color: new THREE.Color(colors.ink),
        roughness: 0.55,
        metalness: 0.2,
        clearcoat: 0.15,
      });
      frameMats.push(frameMat);
    }

    // Top bevel
    const topGeom = new THREE.PlaneGeometry(cardW + 2 * bevelSize, bevelSize);
    const topFrame = new THREE.Mesh(topGeom, frameMats[0]);
    topFrame.position.set(0, cardH / 2 + bevelSize / 2, 0.001);
    cardGroup.add(topFrame);

    // Bottom bevel
    const botGeom = new THREE.PlaneGeometry(cardW + 2 * bevelSize, bevelSize);
    const botFrame = new THREE.Mesh(botGeom, frameMats[1]);
    botFrame.position.set(0, -cardH / 2 - bevelSize / 2, 0.001);
    cardGroup.add(botFrame);

    // Left bevel
    const leftGeom = new THREE.PlaneGeometry(bevelSize, cardH + 2 * bevelSize);
    const leftFrame = new THREE.Mesh(leftGeom, frameMats[2]);
    leftFrame.position.set(-cardW / 2 - bevelSize / 2, 0, 0.001);
    cardGroup.add(leftFrame);

    // Right bevel
    const rightGeom = new THREE.PlaneGeometry(bevelSize, cardH + 2 * bevelSize);
    const rightFrame = new THREE.Mesh(rightGeom, frameMats[3]);
    rightFrame.position.set(cardW / 2 + bevelSize / 2, 0, 0.001);
    cardGroup.add(rightFrame);

    // Accent bar (only on focused card initially)
    const barGeom = new THREE.PlaneGeometry(accentBarW, accentBarH);
    const barMat = new MeshStandardNodeMaterial({
      color: new THREE.Color(colors.accent),
      emissive: new THREE.Color(colors.accent),
      emissiveIntensity: accentEmissive,
      roughness: 0.4,
      metalness: 0,
    });
    const accentBar = new THREE.Mesh(barGeom, barMat);
    accentBar.position.set(0, -cardH / 2 - accentBarH - 0.1, 0.002);
    accentBar.visible = index === 2;
    cardGroup.add(accentBar);
    cardGroup.userData.accentBar = accentBar;

    // Caption text
    const captionText = ctx.fontAtlas.createText(cardTexts[index], {
      fontSize: 18,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: 1.44,
    });
    captionText.position.set(0, -cardH / 2 - accentBarH - 0.25, 0.003);
    captionText.visible = index === 2;
    cardGroup.add(captionText);
    cardGroup.userData.captionText = captionText;

    cardGroup.userData.frameMats = frameMats;
    cardGroup.userData.cardMat = cardMat;

    cardContainer.add(cardGroup);
    cards.push(cardGroup);
  };

  // Load all cards (async)
  const cardPromises = [];
  for (let i = 0; i < numCards; i++) {
    cardPromises.push(createCard(i));
  }

  // ============================================================================
  // APPLY PARALLAX-SCROLL PRIMITIVE
  // ============================================================================
  let parallaxResult = null;

  Promise.all(cardPromises).then(() => {
    parallaxResult = ctx.primitives['parallax-scroll'](group, {
      intensity: parallelIntensity,
    });

    // After parallax is set up, override scroll handler to snap-to-card
    const origHandler = group.userData.handlers?.scroll;
    if (origHandler) {
      group.userData.handlers.scroll = function (e) {
        origHandler(e);

        // Snap-to-nearest card on scroll end (debounced)
        clearTimeout(group.userData.scrollSnapTimeout);
        group.userData.scrollSnapTimeout = setTimeout(() => {
          snapToNearestCard();
        }, 100);
      };
    }
  });

  // ============================================================================
  // SNAP-TO-CARD FUNCTION (weighted-settle motion)
  // ============================================================================
  const snapToNearestCard = () => {
    // Find closest card to x=0
    let closestIdx = 0;
    let minDist = Math.abs(cards[0].position.x);
    for (let i = 1; i < cards.length; i++) {
      const dist = Math.abs(cards[i].position.x);
      if (dist < minDist) {
        minDist = dist;
        closestIdx = i;
      }
    }

    const snapX = (closestIdx - 2) * cardPitch;
    const deltaX = snapX - cards[closestIdx].position.x;

    // Animate all cards to snap position
    gsap.to(cardContainer.position, {
      x: cardContainer.position.x + deltaX,
      duration: 0.9,
      ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
      overwrite: 'auto',
    });

    // Update focus state
    updateFocusCard(closestIdx);
  };

  // ============================================================================
  // FOCUS CARD UPDATE
  // ============================================================================
  const updateFocusCard = (focusIdx) => {
    for (let i = 0; i < cards.length; i++) {
      const card = cards[i];
      const isFocused = i === focusIdx;
      const distance = Math.abs(i - focusIdx);
      const opacityTarget = isFocused
        ? focusOpacity
        : Math.max(maxBlurOpacity, focusOpacity - distance * 0.15);
      const scaleTarget = isFocused ? focusScale : blurScale;

      gsap.to(card, {
        opacity: opacityTarget,
        duration: 0.6,
        ease: 'power2.out',
      });

      gsap.to(card.scale, {
        x: scaleTarget,
        y: scaleTarget,
        duration: 0.6,
        ease: 'power2.out',
      });

      // Counter-rotate focused card to face camera
      const targetRotY = isFocused ? -stripRotY : 0;
      gsap.to(card.rotation, {
        y: targetRotY,
        duration: 0.6,
        ease: 'power2.out',
      });

      // Toggle accent bar and caption visibility
      if (card.userData.accentBar) {
        card.userData.accentBar.visible = isFocused;
      }
      if (card.userData.captionText) {
        card.userData.captionText.visible = isFocused;
      }
    }
  };

  // ============================================================================
  // INITIALIZE CARD STATES (after load)
  // ============================================================================
  Promise.all(cardPromises).then(() => {
    updateFocusCard(2); // Center card (NA-01) is focused initially
  });

  // ============================================================================
  // CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    gsap.killTweensOf(cardContainer.position);
    gsap.killTweensOf(cardContainer.rotation);
    cards.forEach((card) => {
      gsap.killTweensOf(card);
      gsap.killTweensOf(card.scale);
      gsap.killTweensOf(card.rotation);
      if (card.userData.cardMat) {
        card.userData.cardMat.dispose();
      }
      if (card.userData.frameMats) {
        card.userData.frameMats.forEach((mat) => mat.dispose());
      }
    });
    stageMat.dispose();
    cardGeom?.dispose();
    if (mainTexture) {
      mainTexture.dispose();
    }
    if (parallaxResult?.cleanup) {
      parallaxResult.cleanup();
    }
  };

  return group;
}
